"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { createClient } from "@/lib/supabase/client";


export default function MessagesPage(){

  const supabase = createClient();

  const [messages,setMessages] = useState<any[]>([]);
  const [groomer,setGroomer] = useState<any>(null);
  const [reply,setReply] = useState("");
  const [loading,setLoading] = useState(true);



  useEffect(()=>{

    loadMessages();

  },[]);




  async function loadMessages(){


    const {
      data:{user}
    } = await supabase.auth.getUser();



    if(!user){
      return;
    }




    const {data:groomerData,error:groomerError}=await supabase
      .from("groomers")
      .select("*")
      .eq("user_id",user.id)
      .single();



    if(groomerError){

      console.log(groomerError);
      return;

    }



    setGroomer(groomerData);





    const {data:messageData,error}=await supabase
      .from("messages")
      .select("*")
      .eq("groomer_id",groomerData.id)
      .order("created_at",{ascending:true});



    if(error){

      console.log(error);

    }



    setMessages(messageData || []);

    setLoading(false);


  }







  async function sendReply(){


    if(!reply.trim()) return;


    if(!groomer) return;




    const {error}=await supabase
      .from("messages")
      .insert({

        groomer_id:groomer.id,

        sender_type:"groomer",

        message:reply

      });



    if(error){

      alert(error.message);
      return;

    }



    setReply("");

    loadMessages();


  }






  if(loading){

    return (

      <div className="p-10">
        Loading messages...
      </div>

    );

  }






  return (

    <main className="min-h-screen bg-green-50 p-6">


      <div className="max-w-4xl mx-auto relative">



        <Link
          href="/dashboard"
          className="absolute right-0 top-0 bg-red-500 text-white px-4 py-2 rounded-xl"
        >
          ✕
        </Link>




        <h1 className="text-4xl font-bold text-green-700">
          💬 Messages
        </h1>





        <div className="bg-white rounded-3xl shadow p-6 mt-8">





          <div className="space-y-3 max-h-[500px] overflow-y-auto">


            {messages.map((msg)=>(


              <div

                key={msg.id}

                className={`p-4 rounded-xl ${
                  
                  msg.sender_type === "groomer"
                  ? "bg-green-100 text-right"
                  : "bg-gray-100"

                }`}

              >

                <p className="font-bold">

                  {msg.sender_type === "groomer"
                  ? "You"
                  : "Customer"}

                </p>


                <p>
                  {msg.message}
                </p>


                <p className="text-xs text-gray-400 mt-2">

                  {new Date(
                    msg.created_at
                  ).toLocaleString()}

                </p>


              </div>


            ))}



            {messages.length === 0 && (

              <p className="text-gray-400 text-center">
                No messages yet
              </p>

            )}


          </div>







          <div className="flex gap-3 mt-6">


            <input

              className="border rounded-xl p-3 flex-1"

              placeholder="Reply to customer..."

              value={reply}

              onChange={(e)=>setReply(e.target.value)}

              onKeyDown={(e)=>{

                if(e.key==="Enter"){
                  sendReply();
                }

              }}

            />



            <button

              onClick={sendReply}

              className="bg-green-600 text-white px-6 rounded-xl"

            >

              Send

            </button>


          </div>




        </div>


      </div>


    </main>

  );


}